/**
 * Generate the social card served at https://thedannywahl.github.io/pantoken/og.png — the image link
 * scrapers (Slack, iMessage, X, LinkedIn, Discord, Facebook) show when a pantoken docs URL unfurls.
 * Renders a 1200×630 PNG from an inline SVG that reuses the docs theme's home background (the navy
 * field with concentric blue circles bleeding off the bottom-right corner, see
 * `.vitepress/theme/pantoken.css` → `--vp-home-bg-image`) and sets the pantoken wordmark over it with
 * the Instructure red dot as its period.
 *
 * Committed output (not generated at build time), so regenerate and commit when the branding changes:
 * `vp run docs:og` (or `node scripts/gen-og.ts`).
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { Resvg } from "@resvg/resvg-js";

const WIDTH = 1200;
const HEIGHT = 630;

// Palette lifted from the docs theme's home background SVG (pantoken.css `--vp-home-bg-image`) and the
// Instructure logo's red dot.
const NAVY = "#002b4d"; // background field
const RING_1 = "#004880"; // outermost concentric ring
const RING_2 = "#0065b3";
const RING_3 = "#0090ff"; // brightest ring + brand-blue accent
const RED = "#ec1c24"; // Instructure red dot, reused as the wordmark's period
const WHITE = "#ffffff";
const MUTED = "#9db8d6"; // desaturated blue for the supporting line
const URL_FILL = "#cfe3f7";

// The theme background anchors three concentric circles at the bottom-right corner of a 374×160 field
// (radii 200/140/80). Scale those radii to the card width so the card reproduces the same look at
// 1200×630, with the corner at (WIDTH, HEIGHT).
const scale = WIDTH / 374;
const ring = (r: number, fill: string): string =>
  `<circle cx="${WIDTH}" cy="${HEIGHT}" r="${Math.round(r * scale)}" fill="${fill}" />`;

const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
  <rect width="${WIDTH}" height="${HEIGHT}" fill="${NAVY}" />
  ${ring(200, RING_1)}
  ${ring(140, RING_2)}
  ${ring(80, RING_3)}

  <!-- Brand-blue top accent rule. -->
  <rect x="0" y="0" width="${WIDTH}" height="10" fill="${RING_3}" />

  <!-- Wordmark: "pantoken" with the Instructure red dot as its period. -->
  <text x="96" y="266" font-family="Helvetica Neue, Arial, sans-serif" font-size="132" font-weight="700" letter-spacing="-4"><tspan fill="${WHITE}">pantoken</tspan><tspan fill="${RED}">.</tspan></text>

  <!-- Tagline (the home hero line). -->
  <text x="100" y="392" font-family="Helvetica Neue, Arial, sans-serif" font-size="60" font-weight="600" fill="${RING_3}">Instructure design tokens, everywhere</text>

  <!-- Supporting line. -->
  <text x="100" y="452" font-family="Helvetica Neue, Arial, sans-serif" font-size="32" font-weight="400" fill="${MUTED}">One resolved model, reshaped into CSS, native code, framework bindings, and Figma.</text>

  <!-- Footer URL. -->
  <text x="100" y="556" font-family="ui-monospace, Menlo, monospace" font-size="30" font-weight="500" fill="${URL_FILL}">thedannywahl.github.io/pantoken</text>
</svg>`;

const png = new Resvg(svg, {
  fitTo: { mode: "width", value: WIDTH },
  font: { loadSystemFonts: true },
})
  .render()
  .asPng();

const out = fileURLToPath(new URL("../public/og.png", import.meta.url));
writeFileSync(out, png);
console.log(
  `✓ wrote social card → docs/public/og.png (${WIDTH}×${HEIGHT}, ${(png.length / 1024).toFixed(1)} KB)`,
);

